-- 2906 🏋️ Exercises from the book "ren-meulensteen-man-utd-methods-of-success-2007-2013-ren-s-coaching-philosophy-a" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'ren-meulensteen-man-utd-methods-of-success-2007-2013-ren-s-coaching-philosophy-a');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Early balls behind high narrow line', 'combination', 'passive', 'in_possession', 38, 38, 'Pattern of Play Example 1', 'Meulensteen (Man Utd, Ferguson era)', 'Hit early forward passes into the space behind a high, narrow back four, timing runs to stay onside.', 'Reds in a 4-4-2 with GK; 4 mannequins stand in as the opponent''s high, narrow back line and 6 blue players act as passive opponents in midfield and attack.', 'Build from a centre back into a central midfielder, who looks to slip a forward through the gap for a run in behind. Variations: the midfielder plays diagonally behind the centre backs for the far winger to run onto and finish or square; or a centre back switches to his partner, who hits a long early ball for the opposite winger who drifted inside and then ran in behind.', NULL, 'Three variations: central through ball for striker; diagonal ball for wide winger; long pass from centre back for winger.', 'Look for the early pass behind; runners time movement to stay onside; finish or square for a team-mate.', '11 reds v 6 passive blues + 4 mannequins', 17, 17, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 10),
  ('Midfielder rotates out, switch for 5v4', 'combination', 'passive', 'in_possession', 39, 39, 'Pattern of Play Example 2', 'Meulensteen (Man Utd, Ferguson era)', 'A central midfielder drops wide into a back three and the team switches play to create a 5v4 attack against a middle-height narrow line.', 'Reds in a 4-3-3 with GK; 4 mannequins as a mid-height narrow back line, 6 passive blue opponents.', 'Centre back plays to the midfielder who has rotated out; ball goes into the other central midfielder (or forward to the advanced full back), who switches out wide to the opposite full back while the winger tucks inside. Full back finds the inside winger or crosses behind for the striker; ball is laid back to the attacking midfielder, who threads it between the centre backs for the far winger''s run to score.', NULL, 'Options at each step depend on how the blues press (inside pass vs ball behind the line).', 'Rotation to form a back three; switch quickly; wingers come inside to free the full back; well-timed runs in behind.', '11 reds v 6 passive blues + 4 mannequins', 17, 17, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Midfielder rotates in, play through deep line', 'combination', 'passive', 'in_possession', 40, 40, 'Pattern of Play Example 3', 'Meulensteen (Man Utd, Ferguson era)', 'With a midfielder dropping between the centre backs, play through the press and break down a deep, narrow defence.', 'Reds in a 4-4-2 with GK; 4 mannequins as a deep narrow back line, 3 mannequins as central midfielders, 3 passive blue forwards.', 'GK plays to the midfielder dropping in, who is pressed and gives to a centre back; the centre back carries the ball forward and passes through the lines to a central midfielder or to the advanced full back. Ball goes out to the winger, who either feeds the striker near the box or dribbles down the line and crosses; striker can slide a through ball for the far winger''s run in behind to score.', NULL, 'Wide option: winger crosses after dribbling up the line instead of passing inside.', 'Centre back drives forward when pressed; pass through lines; runs in behind from the far side avoiding offside.', '11 reds v 3 passive blues + 7 mannequins', 14, 14, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Quick combinations v very deep narrow line', 'combination', 'passive', 'in_possession', 41, 41, 'Pattern of Play Example 4', 'Meulensteen (Man Utd, Ferguson era)', 'Quick one-two touch play around the box with back-post runs and deliveries against a very deep, narrow block.', 'Reds in a 4-3-3 with GK pushed into the attacking half; full backs very high, 3 midfielders central, 2 forwards in the box; 4 mannequins on the box edge as the back line and 6 passive blues.', 'With the winger on the ball at the side of the box, options: find the overlapping full back to cross; play back to a midfielder who passes to another midfielder to shoot or move forward; switch to the far-side full back to cross; or cross to the back post for the forwards.', NULL, 'Four different options from the same starting position.', 'Shift the ball quickly; overlaps from full backs; aim deliveries to the back post; shoot when space opens.', '11 reds v 6 passive blues + 4 mannequins', 17, 17, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Early balls behind high wide line', 'combination', 'passive', 'in_possession', 43, 43, 'Pattern of Play Example 5', 'Meulensteen (Man Utd, Ferguson era)', 'Play forward early into the space behind a high, wide defensive line, using full backs to find central runs.', 'Reds in a 4-4-2 with GK; 4 mannequins as a high back line spread wide, 6 passive blue opponents.', 'Centre back to central midfielder to full back; the full back plays forward early, slotting the ball between the right back and centre back for the striker running in behind to finish. Repeat on the other side: centre back to full back, who carries it up and curls a ball round for the second forward''s run.', NULL, 'Run the same pattern down both sides of the pitch.', 'Full backs look for early passes into central spaces behind the back four; forwards time runs to stay onside.', '11 reds v 6 passive blues + 4 mannequins', 17, 17, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Wingers inside, full backs high v mid wide', 'combination', 'passive', 'in_possession', 44, 44, 'Pattern of Play Example 6', 'Meulensteen (Man Utd, Ferguson era)', 'Attack a mid-height, wide back line with wingers coming inside and full backs pushing on.', 'Reds in a 4-3-3 with GK; 4 mannequins as a mid-height wide back line, 6 passive blue opponents.', 'Centre back to midfielder dropping in as a back three; across to the other centre back, who passes inside to a midfielder or carries forward and finds the advanced full back. Ball worked inside to the other midfielder or switched to the far full back; the inside winger receives between the lines, then plays the striker in behind, or the full back dribbles and crosses. Finish from the through ball or a back-post cross.', NULL, 'Alternatives at most steps (switch to far full back, full back dribbles and crosses).', 'Wingers come inside to free full backs, find space between lines or run into the box.', '11 reds v 6 passive blues + 4 mannequins', 17, 17, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Rotate out, receive and play behind', 'combination', 'passive', 'in_possession', 45, 45, 'Pattern of Play Example 7', 'Meulensteen (Man Utd, Ferguson era)', 'One central midfielder drops wide to form a back three while the others receive and play in behind a deep, wide line.', 'Reds in a 4-3-3 with GK; 4 mannequins as the deep wide back line, 4 passive blue midfielders and 2 blue forwards.', 'Midfielder rotates out, full backs push on; he passes to a centre back or straight into a midfielder, who plays behind for the winger or striker running off defenders'' shoulders. Or play continues: across to the other centre back, into the winger dropping between lines, to an attacking midfielder, who sends the left back sprinting into space vacated by the winger to create a chance.', NULL, 'Same pattern mirrored on the other side.', 'Runs off the shoulder of defenders; winger drops to receive, full back exploits the space he leaves.', '11 reds v 6 passive blues + 4 mannequins', 17, 17, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Box combinations and wide overloads v very deep', 'combination', 'passive', 'in_possession', 46, 46, 'Pattern of Play Example 8', 'Meulensteen (Man Utd, Ferguson era)', 'Quick one-two touch play round the box, 1v1/2v1 wide and back-post runs against a very deep wide block.', 'Reds in a 4-3-3 with GK; 6 mannequins as the opponent''s midfield and attacking lines, 4 passive blue defenders in and around the box.', 'Centre back to midfielder, to full back, back to the other centre back; midfielder feeds an attacking midfielder on the box edge, who can pass wide to the full back or combine; centre back switches to the far winger. Attacking midfielder plays a one-touch pass for a midfielder''s run or shoots himself, or the winger passes to the overlapping full back to cross; a short pass inside lets a midfielder shoot first time.', NULL, 'Several options from each phase (shoot, overlap and cross, first-time finish).', 'Full backs hold width or time runs; centre backs switch when in space and act as rest defence; quick combinations round the box; look for 1v1 or 2v1 wide.', '11 reds v 4 passive blues + 6 mannequins', 15, 15, 'Full pitch (attacking half emphasis)', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Two-ball routine: one-two shot, wide cross', 'combination', 'unopposed', 'in_possession', 73, 73, '2-Ball Routine (Variation 1)', 'Rene Meulensteen (Man Utd)', 'Quick combination play and a shot from outside the box followed straight away by a cross and box runs.', 'Half pitch with a GK in goal and mannequins as defenders around the box. Central midfielders/forwards queue at positions A and B, full backs/wingers at wide positions C and D; coach holds a supply of balls near the centre circle.', 'Ball 1: A plays into B, gets the lay-off back, dribbles to open an angle and shoots. As soon as A shoots the coach feeds a second ball to C, who opens up, dribbles forward and crosses while B and D attack the box to finish.', 'Players rotate A to B, B to A; wide players return to their own positions. Can be run from either flank.', NULL, NULL, 'Groups at 4 positions + GK + coach', NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Two-ball routine: run in behind, deep cross', 'combination', 'unopposed', 'in_possession', 74, 74, '2-Ball Routine (Variation 2)', 'Rene Meulensteen (Man Utd)', 'Through-ball timing for a run in behind, then a second ball crossed from deep.', 'Same half-pitch layout as variation 1: A and B central, C and D wide, mannequins as defenders, GK, coach with balls.', 'A passes to B who drops off at an angle and slips a through pass for A running in behind to shoot. When A has shot the coach gives a new ball to D, who crosses early from deep for B and C to attack the box.', 'Rotation A to B, B to A, wide players back to their spots. Crosses from either side.', NULL, NULL, 'Groups at 4 positions + GK + coach', NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Two-ball routine: overlap and cut-back', 'combination', 'unopposed', 'in_possession', 75, 75, '2-Ball Routine (Variation 3)', 'Rene Meulensteen (Man Utd)', 'Lay-off and through pass to finish, then an overlap down the flank ending in a cut-back, used against deep defences.', 'Same layout: A and B central, wide players at C and D, mannequins, GK, coach feeding.', 'A plays into B, takes the lay-off and passes through for B to run onto and shoot. The coach then feeds C (or D), who passes for the overlapping run of another wide player; that player drives to the byline and cuts back or crosses to the back post while A and D attack the box.', 'A and B swap; wide players keep working out wide, including the overlapper.', NULL, 'Weighted, accurate passes and soft lay-offs; quality finishing; wide players receive on the front foot, commit the mannequin and release on time; quality final ball (cross or cut-back).', 'Groups at 4 positions + GK + coach', NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Multi-ball routine vs 2 centre backs, 5v2 finish', 'combination', 'overload', 'in_possession', 76, 79, '3 or 4-Ball Routine (2 Defenders)', 'Rene Meulensteen (Man Utd)', 'Waves of attack in positions: a central combination, an early cross, a second cross from the full back and a free 5v2 attack.', 'Half pitch with players in their match positions (4 central mids, 2 forwards, wingers and full backs on both sides), 2 live centre backs defending the box, mannequins for the opposition full backs and midfield, 1-2 GKs and coaches with balls.', 'Ball 1: CM plays into a forward, who passes across to the other forward, who slips the CM in behind between the centre backs to shoot. Ball 2: a CM switches to the other CM who plays the winger in high for an early cross with 3 runners (near post, back post, penalty spot) while the full back pushes on. Ball 3: coach plays to the advanced full back (or winger) to dribble and cross or cut back again. Optional ball 4: coach feeds a CM and the 5 central players attack the 2 centre backs freely.', NULL, 'Can be done to either flank using wingers and full backs.', 'Quick one and two touch play without rushing; play around or through to break lines; recognise forward runs and key passes; clever through balls, switches and diagonals to the back post; quality final ball.', '9-21 red players, 2 defenders, 1-2 GKs', 12, 25, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Multi-ball routine vs back four, 7v4 finish', 'combination', 'overload', 'in_possession', 80, 82, '3 or 4-Ball Routine (4 Defenders)', 'Rene Meulensteen (Man Utd)', 'Switching play and crossing in waves, finishing with a free 7v4 attack against a back four.', 'Half pitch with players in positions (set-up as on p76), 4 live blue defenders, 4 blue mannequins as midfielders, 1-2 GKs, coaches with balls.', 'Ball 1: central combination through the forwards ending with the CM running in behind to shoot. Ball 2: CM to CM, long switch to the winger, who comes inside and sends the overlapping full back down the line to cross or cut back for 3 runners. Ball 3: coach feeds the winger (or full back) on that side to dribble and cross. Ball 4: coach feeds a CM and 7 attackers (with only full backs or wingers joining) play freely against the 4 defenders.', NULL, 'Crosses from either flank using wingers and full backs.', 'Quick one and two touch play without rushing; break lines around or through; spot forward runs; clever through balls, switches and diagonals; quality crosses and cut-backs.', '9-21 red players, 4 defenders, 1-2 GKs', 14, 27, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Attacking wave in pairs, unopposed', 'combination', 'unopposed', 'in_possession', 84, 84, 'Attacking Wave in Pairs: Unopposed', 'Rene Meulensteen (Man Utd)', 'Fast attacks through the middle using link players and forward runs in behind.', 'Full pitch with a GK at each end, 8 mannequins as a defending team (midfield line and back line) in the middle, 2 yellow link players between the lines, red players waiting in pairs at both ends.', 'The GK passes out to a red player, who plays forward into the first link player and gets it back, then passes through the midfield line to the second link player. He controls between the lines and slides a pass between the centre backs for the other red player''s deep run to finish. Runs both directions with many combination options.', NULL, NULL, 'Vary pass speed, slower then pick the moment to catapult the attack quickly through the middle and in behind.', '8-10 red players in pairs, 2 link players, 2 GKs', 12, 14, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Attacking wave in pairs, opposed', 'combination', 'opposed', 'in_possession', 85, 85, 'Attacking Wave in Pairs: Opposed', 'Rene Meulensteen (Man Utd)', 'Break quickly through the middle when two live centre backs pressure the link players.', 'As the unopposed version, with 2 active blue centre backs added among the mannequins.', 'GK passes to a red player, who passes across to his partner, who plays through the midfield line to the advanced link player. Pressed by a centre back, he plays back to the second link player while both reds make forward runs; the link player can play in behind for a red or a link player runs into the box to receive and score.', NULL, NULL, 'Break quickly into the heart of the defence; create, keep and change rhythm; mix straight and diagonal (crossing) runs; be clinical; supporting player follows up for rebounds.', '8-10 red players in pairs, 2 link players, 2 defenders, 2 GKs', 14, 16, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Attacking wave in threes, unopposed', 'combination', 'unopposed', 'in_possession', 86, 86, 'Attacking Wave in Threes: Unopposed', 'Rene Meulensteen (Man Utd)', 'Three-player attacks using link players to break both lines and a quality final ball for timed box runs.', 'Full pitch, GK each end, 8 mannequins as the defending team, 2 link players in the middle, reds in threes at each end.', 'GK serves a wide red player, who passes into the most advanced link player; he sets the second link player, who plays in behind the midfield line to the side where the middle red has drifted. That player dribbles on and crosses while the other two time runs into the box to score.', 'First pass must go to the most advanced link player; all 3 reds must break the lines; second link player supports and passes to a red running beyond the mannequin back line.', NULL, 'Quality final ball matched with well-timed box runs.', '9 or 12 red players in threes, 2 link players, 2 GKs', 13, 16, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Attacking wave in threes, opposed', 'combination', 'opposed', 'in_possession', 87, 87, 'Attacking Wave in Threes: Opposed', 'Rene Meulensteen (Man Utd)', 'Three-player attacking waves against two live defenders, choosing the release based on their positioning.', 'As the threes unopposed set-up, with 2 active blue defenders added.', 'GK serves a wide red, who plays into the advanced link player; he sets the supporting link player, who passes in behind the midfield line to a red making a forward run on that side. He receives beyond the defensive line and cuts the ball back for a team-mate to score.', NULL, NULL, 'Slow then catapult the attack; one touch when possible; decide from the defenders'' positions; if the centre is crowded find the release outside; be clinical; follow up rebounds.', '9-12 red players in threes, 2 link players, 2 defenders, 2 GKs', 15, 18, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Attacking wave in fours, unopposed', 'combination', 'unopposed', 'in_possession', 88, 88, 'Attacking Wave in Fours: Unopposed', 'Rene Meulensteen (Man Utd)', 'Four-player attacks with link players and a quick switch of play to unbalance the defence.', 'Full pitch, GK each end, 8 mannequins as the defending team, 2 link players, reds in fours (2 wide, 2 central) at each end.', 'GK serves a wide red, who plays into the first link player; he sets a central red, who plays through the midfield line to the second link player. That player lays it to the other central red, who switches to the far wide player or plays short. The wide player dribbles on and cuts back for the central runners to finish.', NULL, NULL, 'Switch the play quickly to unbalance the opposition.', '12 red players in fours, 2 link players, 2 GKs', 16, 16, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Attacking wave in fours, opposed', 'combination', 'opposed', 'in_possession', 89, 89, 'Attacking Wave in Fours: Opposed', 'Rene Meulensteen (Man Utd)', 'Game-realistic four-player build-up through the middle and wide against two live defenders.', 'As the fours unopposed set-up, with 2 active blue defenders added.', 'GK passes to a central red, who sends the wide player away; he passes through the midfield line to the advanced link player, who sets the supporting link player. That player clips an aerial pass in behind for the deep run of the far wide red (or any of the others, who all run beyond), who crosses for runners to the penalty spot, near post and back post.', NULL, NULL, 'Paint the picture at the start to cut stoppages; break lines at pace, push full backs wide, rotate link players; switch quickly; decide crosses and box runs from the defenders'' positions; go late, arrive fast.', '12 red players in fours, 2 link players, 2 defenders, 2 GKs', 18, 18, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Three-ball attacking waves overload game', 'small_sided_game', 'overload', 'in_possession', 90, 91, 'Attacking Wave Game: 3-Ball Attacking Waves Overload Game', 'Rene Meulensteen (Man Utd)', 'Use numerical overloads (8v5, 2v1 and 3v2 wide) to attack fast, with an immediate change of mindset when the ball is lost.', 'Pitch with a goal and GK at each end, three teams of 5 (reds, blues, whites resting behind one goal) plus 3 yellow link players who join whichever team has the ball; coach on the side with balls.', 'Ball 1: coach plays to the reds'' GK; centre backs split wide and full backs push up, a CB plays forward into a link player and the reds attack 8v5, aiming to score within 20 seconds and create 2v1s wide. If blues win it they counter 8v5 with the link players. Ball 2: coach gives the reds a new ball to repeat. Ball 3: coach gives the blues a ball to counter-attack 8v5. After 3 balls the whites replace the reds.', 'Attack must try to score within about 20 seconds; whites wait out until the 3 phases are done; team sizes can be 5, 6 or 7.', NULL, 'Quick one and two touch play without rushing; break lines around or through; keep width and switch; spot forward runs; quality crosses and cut-backs; on a turnover the winners sprint forward and the losers sprint back.', '3 teams of 5 + 3 link players + 2 GKs', 20, 26, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Fergie Time late-goal scenario game', 'conditioned_game', 'opposed', 'in_possession', 99, 103, '"Fergie Time" Scenario Practice Example (3 Phases)', 'Rene Meulensteen / Sir Alex Ferguson (Man Utd)', 'Train the team to chase a late goal against a deep block with composure, rest defence and escalating tactical changes.', '11v11 on a full pitch: reds in 4-3-3 with full backs pushed high and centre backs plus a CM as rest defence; blues in a deep 5-4-1 or 4-5-1 protecting a lead. Clock starts at 80:00 with 10 minutes plus 4 stoppage time to play; reds are losing or drawing and must win.', 'Starts when a red receives the first pass from the coach, then real match rules. Phase 1 (4 min): wingers tuck in to make 3v4 with the CF, full backs push up, opposite winger and a CM attack the box. Phase 2 (4 min): add an extra forward, wingers high and wide, full backs higher, a CM makes late runs and shoots from distance, keep a numerical edge at the back. Phase 3 (6 min): push a centre back and both CMs forward and flood the box for rebounds and deflections, one CB stays as rest defence.', 'Normal match laws (offside, free kicks, corners, throw-ins). Targets: 7-8 balls into the box over the 14 minutes, 5-6 in the last 10, 3-4 in the last 6; one of them must become a goal. Move to the next phase only if no goal yet.', 'Three timed phases with increasingly drastic tactical changes (see proc).', 'Keep composure and quality - rushing kills the final ball; maximise every second; stay positive; win free kicks in dangerous zones; always keep rest defence behind the ball.', '11v11', 22, 22, 'Full pitch', NULL, NULL, 14.0, true, true, true, NULL, 210),
  ('Up and down turns at a mannequin', 'technical', 'unopposed', 'in_possession', 141, 141, 'Opponent at Side: Up and Down Moves - 1', 'Rene Meulensteen (Man Utd)', 'Turning back the opposite way when a defender closes you down from the side.', 'Square with a mannequin in the centre; four lines of players start at the midpoints of each side (A and B opposite each other, C and D on the other two sides), each with balls.', 'A and B dribble at the central mannequin and, just before reaching it, perform an up and down turn back the way they came, then pass to the next player in their own line. C and D go as soon as A and B have turned away, and so on.', NULL, 'Chain 3 turns in a row before passing on; use both feet and mix different moves.', 'Close control on the dribble; start the turn at the right distance from the mannequin; pick from stop turn, inside/outside hook chop, step-over, Cruyff turn, turn with the front of the foot; use both feet.', '4 lines of 2-3', 8, 12, NULL, NULL, NULL, 8.0, false, false, false, NULL, 220),
  ('Up and down turn, then pass round the square', 'technical', 'unopposed', 'in_possession', 142, 142, 'Opponent at Side: Up and Down Moves - 2', 'Rene Meulensteen (Man Utd)', 'Up and down turns away from a side challenge combined with first touch and passing.', 'Square with a central mannequin and four lines at the side midpoints (A, B, C, D), as in the previous practice.', 'A and B dribble to the mannequin, turn back with an up and down move, then pass to the next player in their own line, who plays the ball on to the C or D line. C and D then dribble in and repeat; the circulation runs anti-clockwise.', NULL, 'Players turn at the side of the mannequin instead of in front of it; switch to clockwise rotation.', 'Close control towards the mannequin; leave enough space to get away; correct body shape and footwork in the turn; work both feet and both directions.', '4 lines of 2-3', 8, 12, NULL, NULL, NULL, 8.0, false, false, false, NULL, 230),
  ('Double up and down move plus pass', 'technical', 'unopposed', 'in_possession', 143, 143, 'Opponent at Side: Up and Down Moves - 3', 'Rene Meulensteen (Man Utd)', 'Two changes of direction in a row to escape a side challenge and then move away again.', 'Same square: central mannequin with four lines at the side midpoints.', 'A and B dribble to the side of the mannequin, do an up and down move, then immediately a sideways move (e.g. Cruyff or step-over) to change direction again. They pass to the next player in line on the opposite side, who feeds C or D to repeat; anti-clockwise rotation.', NULL, 'Reverse to clockwise.', 'Dribble at speed with close control; shield the ball during the up and down move; link straight into the sideways move; both feet, both directions.', '4 lines of 2-3', 8, 12, NULL, NULL, NULL, 8.0, false, false, false, NULL, 240),
  ('2v2 plus end players, up and down moves', 'one_v_one', 'opposed', 'in_possession', 144, 144, 'Opponent at Side: Up and Down Moves - 4', 'Rene Meulensteen (Man Utd)', 'Using up and down moves to change direction under live pressure in a game.', 'Rectangle split into two halves with end zones; 2v2 in one half, each team with 2 outside players on the end lines; coach with balls at the side.', 'The team on the ball keeps possession by combining with its outside players and turning away from markers with up and down moves. If the defenders win it they try to keep it the same way. Play 2-minute games, then rotate the outside players in.', 'Possession game 2(+2) v 2(+2).', 'After passing to an end player, the passer swaps places with him; the new inside player attacks the space ahead and uses an up and down move to switch direction quickly.', 'Know where the opponent is; decide well between passing and turning; shield by keeping the body between opponent and ball.', '2v2 +2 +2', 8, 8, NULL, NULL, NULL, 8.0, false, false, false, NULL, 250),
  ('Spin-off turns at angled mannequins', 'technical', 'unopposed', 'in_possession', 146, 146, 'Opponent at Side: Spin-off Moves - 1', 'Rene Meulensteen (Man Utd)', 'Spinning away from a defender who approaches at an angle.', 'Area with two mannequins either side of a central cone on the halfway line; players in pairs (A and B) at both ends.', 'A dribbles at an angle towards the side of a mannequin, performs an angled spin-off turn away in the opposite forward direction, and passes to B at the far end, who repeats it on the other mannequin; clockwise rotation.', NULL, 'Switch to anti-clockwise so the spin-offs come from the other angle.', 'Close control on the dribble; keep enough distance from the mannequin; turn away with body between ball and opponent.', '2 pairs or small groups', 4, 8, NULL, NULL, NULL, 8.0, false, false, false, NULL, 260),
  ('Spin-off moves under passive angled pressure', 'one_v_one', 'passive', 'in_possession', 147, 147, 'Opponent at Side: Spin-off Moves - 2', 'Rene Meulensteen (Man Utd)', 'Turning away from an opponent who closes down at an angle, with a live but passive defender.', 'Area with a cone on each side of the halfway line; player A (passer/defender) at one end, receiver B at the other end with a waiting line.', 'A passes to B, who takes a first touch towards the left or right cone. As B dribbles, A crosses over to close him down passively; at the right moment B spins away in the opposite forward direction and passes to the next player waiting. Receivers alternate cones to work both sides.', NULL, NULL, 'First touch chops the ball into space towards the cone; dribble at speed with control; keep distance from the defender while turning; shield the ball; accelerate away.', 'groups of 3-4', 3, 8, NULL, NULL, NULL, 8.0, false, false, true, NULL, 270),
  ('4v4 to four mini goals, spin-offs', 'small_sided_game', 'opposed', 'in_possession', 148, 148, 'Opponent at Side: Spin-off Moves - 3', 'Rene Meulensteen (Man Utd)', 'Shifting the ball and using turns to change the angle of attack and score on the weak side.', 'Pitch split down the middle with a mini goal in each corner; each team attacks the two goals at one end.', 'Normal 4v4. Players use spin-off moves to turn away from opponents and move the ball quickly to score in either goal. After a goal or ball out over the goal line the other team restarts.', 'Coach can add extra rules to challenge players.', 'Various added rules as variations.', 'Width and depth in possession; move the ball quickly; 1-2 touch to drag opponents to one side; disguise the attack on one goal then turn and go to the other.', '4v4', 8, 8, NULL, NULL, NULL, 12.0, true, false, true, NULL, 280),
  ('Frontal 1v1 vs line-bound defender', 'one_v_one', 'opposed', 'in_possession', 150, 150, 'Direct Frontal 1v1 - 1', 'Rene Meulensteen (Man Utd)', 'Moves to beat a defender who is directly in front.', 'Two parallel channels, each with an attacking line at one end, a receiver at the other end and a defender on a line across the middle; spare defenders wait at the side.', 'The attacker drives at speed at the defender, who may only move sideways along the middle line. After beating him the attacker passes to the player at the far end, who comes back the other way.', 'Defender confined to the line; defenders count balls won; rotate defenders every 2-3 minutes.', NULL, 'Drive at speed with close control; keep enough distance while doing the move; be unpredictable and accelerate away; defenders take a sideways-on stance.', '2 groups of 4-5', 8, 10, NULL, NULL, NULL, 12.0, false, false, true, NULL, 290),
  ('Frontal 1v1 vs defender in a square', 'one_v_one', 'opposed', 'in_possession', 151, 151, 'Direct Frontal 1v1 - 2', 'Rene Meulensteen (Man Utd)', 'Beating a frontal defender who can now move anywhere inside a square.', 'Two channels each with a central square zone holding a defender; attackers at one end, receiver at the other, spare defenders outside.', 'Attacker dribbles at speed at the defender in the square, beats him with a move and passes to the player at the far end, who repeats the other way.', 'Defender may only defend inside his square; defenders count balls won; change defenders every 2-3 minutes.', NULL, 'Speed with close control; keep distance as you do the move; unpredictability and acceleration away; defender sideways-on, ready to turn and challenge within the square.', '2 groups of 4-5', 8, 10, NULL, NULL, NULL, 12.0, false, false, true, NULL, 300),
  ('Spin away from defender behind', 'technical', 'passive', 'in_possession', 153, 153, 'Opponent Challenging from Behind: Turn Away or Spin-Off', 'Rene Meulensteen (Man Utd)', 'Spin-off turns to get away from a marker challenging from behind.', 'Two channels, each with a middle square holding a receiver marked from behind by a defender; servers A and B at the two ends.', 'A passes into the middle player, who is passively marked from behind; he spins 180 degrees away from the defender and passes to B at the other end. Repeat from B''s side; rotate the middle defender after 4 repetitions.', NULL, 'The defender increases pressure on the receiver.', 'Well-weighted passes to the correct foot; create space to perform the turn; quick, sharp turns.', '2 groups of 4', 8, 8, NULL, NULL, NULL, 12.0, false, false, true, NULL, 310),
  ('Edge of box receive and finish, six angles', 'finishing', 'unopposed', 'in_possession', 166, 168, 'Individual Finishing Practice 1 (1a-1c)', 'Rene Meulensteen (Man Utd)', 'Good technique, decisions and accurate finishing after receiving at the edge of the box from varied angles.', 'Two mannequins on the edge of the box with attackers A and B beside them; two coaches serve from six numbered positions around the box; GK in goal with coloured bibs hung in the goal corners.', 'Coach 1 feeds A from positions 1, 3, 5 and coach 2 feeds B from 2, 4, 6; players do 2 x 4 reps from each spot before moving to the next. From the angled pass A sets and shoots first time; B, back to goal, spins off the mannequin, opens up and shoots first time.', 'Coach can call a bib colour the shot must aim for.', '1b: A takes one touch across the body (chop) then shoots; B turns (outside/inside/Cruyff) out of his feet and shoots with second touch. 1c: A receives from behind and dribbles past the mannequin with a move (scissors, step-over, drag) to shoot; B moves off the mannequin for a side pass and finishes one touch.', 'Open the body to set up the shot; swing arm over the ball, plant foot beside it, strike with laces or inside and follow through; react quickly to coach calls.', '2 coaches + 2-4 players + GK', 3, 7, 'Edge of penalty area', NULL, NULL, 15.0, true, true, true, NULL, 320),
  ('Close range finishing from low crosses', 'finishing', 'unopposed', 'in_possession', 169, 169, 'Individual Finishing Practice 2', 'Rene Meulensteen (Man Utd)', 'Close range one-touch finishing from balls across the six-yard box and cut-backs.', 'A coach with balls on each side of the box; two mannequins inside the box; three attackers (A centre, B back post, C) start near the edge of the area; GK in goal.', 'Coach 1 drives a low hard ball across the six-yard box for A (near post run) and B (back post). Coach 2 feints a second cross then cuts it back for C, who dummies past the mannequin and peels off to shoot first time near the penalty spot.', 'Coach can call a bib colour to aim at.', NULL, 'One-touch with inside of foot at the posts, instep or inside centrally; time the run, arrive late and fast, good connection.', '2 coaches + 3 players + GK', 6, 6, 'Penalty area', NULL, NULL, 15.0, true, true, true, NULL, 330),
  ('Receive wide, cut inside and curl', 'finishing', 'unopposed', 'in_possession', 170, 170, 'Individual Finishing Practice 3', 'Rene Meulensteen (Man Utd)', 'Cutting in from a wide spot on the edge of the box to score in the far bottom or top corner.', 'Two coaches with balls deep outside the box; attackers A (left) and B (right) wide at the box edge each with a mannequin inside them; C central; GK in goal with coloured bibs in corners.', 'Coach 1 feeds A, who dribbles inside past the mannequin and aims for the opposite corner; then coach 2 feeds B who does the same from the right. C follows each shot in for rebounds.', 'Coach can call a target bib colour.', NULL, 'Dribble at pace and push the ball past the mannequin; curl with instep away from the GK; beat the defender on the inside to move from zone 3 to zone 2.', '2 coaches + 3 players + GK', 6, 6, 'Edge of penalty area', NULL, NULL, 15.0, true, true, true, NULL, 340),
  ('Outside box receive, one-two and volley', 'finishing', 'unopposed', 'in_possession', 171, 172, 'Individual Finishing Practice 4 (4a-4b)', 'Rene Meulensteen (Man Utd)', 'Finishing in different ways after receiving just outside the box, incl. combinations and aerial balls.', 'Two coaches wide with balls; two mannequins at the edge of the box; attacker A near the arc, B further out, a forward inside the box; GK in goal.', 'Coach 1 passes back at an angle to A who sets and shoots first time. Coach 2 feeds B outside the box who plays a one-two with the forward, runs into the box and finishes one touch.', 'Coach can call a target bib colour.', '4b: coaches hit aerial balls from the sides; A controls with chest/thigh/foot and shoots on second touch; B, back to goal, turns off the mannequin and volleys first time.', 'Come off the mannequin and set for 1-2 touch finish; correct body part for height of ball; watch the ball onto the foot for the volley.', '2 coaches + 3 players + GK', 6, 6, 'Edge of penalty area', NULL, NULL, 15.0, true, true, true, NULL, 350),
  ('Four 1v1 skills finishing circuit', 'finishing', 'unopposed', 'in_possession', 174, 174, 'Group Finishing Practice 1', 'Rene Meulensteen (Man Utd)', 'Rehearse all four key 1v1 moves in different positions then finish.', 'Half pitch with goal and GK; mannequins placed as opponents in midfield; players at stations A (by-line), B and C (touchline), D (halfway), E (inside) on both sides.', 'A dribbles up from the by-line and passes to B, who lays off for C; C passes to D on halfway; D plays a short diagonal to E, who spins off the first mannequin, does an up-and-down move at the next, a spin-off at the angled one and a frontal 1v1 move at the last, then dribbles in and shoots. Players rotate A to B to C to D to E and switch sides.', 'One-touch passes where possible.', NULL, 'High speed with many different moves; book notes it was a first-team favourite.', 'Group, 5 stations each side + GK', NULL, NULL, 'Half pitch', NULL, NULL, 10.0, true, true, true, NULL, 360),
  ('Take-over finishing circuit', 'finishing', 'unopposed', 'in_possession', 175, 175, 'Group Finishing Practice 2', 'Rene Meulensteen (Man Utd)', 'Use a take-over from a dribbling team-mate to change direction quickly, beat a defender frontally and finish.', 'Half pitch with GK and goal; mannequins in midfield; stations A to E on each side as in the 1v1 circuit.', 'A dribbles up and passes to B, who passes to C on halfway; C drives a diagonal ground pass for D running across from the far side; D dribbles at a mannequin and backheels with disguise for E to take over; E beats the next mannequin and shoots, then players rotate and switch sides.', 'One-touch passes where possible.', NULL, 'Drive at pace with close control; receive on back foot; time D''s run and the backheel; good first touch and clean finish.', 'Group, 5 stations each side + GK', NULL, NULL, 'Half pitch', NULL, NULL, 10.0, true, true, true, NULL, 370),
  ('Angled shooting with rebounds', 'finishing', 'unopposed', 'in_possession', 176, 176, 'Group Finishing Practice 3', 'Rene Meulensteen (Man Utd)', 'Shift the ball away from a defender at the box edge and finish from an angle, then follow in for rebounds.', 'Two servers in the centre circle; a line of reds on one side and blues on the other near the box corners; a mannequin at each edge of the box; GK in goal.', 'A server plays a hard diagonal pass (or aerial) to the red, who controls inside, makes a quick change of direction past the mannequin, dribbles in and curls a shot to the far corner; the blue from the opposite side runs in for rebounds. Repeat from the other server to the blue side.', NULL, NULL, 'Firm accurate service; control towards the mannequin; keep distance when beating it; choose the right finish; rebound player ruthless.', '2 servers + 2 lines + GK', NULL, NULL, 'Penalty area and arc', NULL, NULL, 10.0, true, true, true, NULL, 380),
  ('Team finishing with servers in box', 'finishing', 'unopposed', 'in_possession', 177, 177, 'Group Finishing Practice 4', 'Rene Meulensteen (Man Utd)', 'Different finishes from varied service and link-play inside the box.', 'Two goals with GKs facing each other across a shortened pitch; groups of 4 (2 servers wide, 2 finishers) at each end, mannequins in the area.', 'Group 1 finishers take turns receiving deliveries from the two servers and finish first time or after control. Group 2 finishers combine (e.g. aerial pass then 1-2) to set up a finish. After 4 finishes servers and finishers swap.', 'Bibs in goal corners can be used as targets.', NULL, 'Accurate varied service; good first touch; quick composed finishing; imaginative link-play; know when to finish with one touch.', 'Groups of 4 + 2 GKs', 10, NULL, NULL, NULL, NULL, 10.0, true, true, true, NULL, 390),
  ('3v3 plus 2 link players to goals', 'small_sided_game', 'overload', 'in_possession', 178, 178, 'Group Finishing Practice 5', 'Rene Meulensteen (Man Utd)', 'Practise different finishes in a competitive high-tempo game.', 'Area between two goals with GKs; two teams of 3 plus 2 neutral link players for the team on the ball; coach with spare balls at the side.', 'Normal 3v3 game, starting from the GK who distributes short, medium or long. The team on the ball uses the 5v3 advantage to create space and shoot as often as possible.', '1-3 touches max; ball out of play restarts from the GK.', NULL, 'Get into finishing positions; know when to show and when to run in behind; calm when finishing; shoot early.', '3v3 (+2) + 2 GKs', 10, 10, NULL, NULL, NULL, 15.0, true, true, true, NULL, 400),
  ('10v10 possession gate game', 'possession', 'opposed', 'in_possession', 188, 188, 'AC Milan Session Example 1: Practice 3', 'Rene Meulensteen (Man Utd)', 'Keep possession at varied tempos and close down, as preparation for AC Milan.', '50 x 50 yard area with gates at the ends to dribble through.', 'One team defends and closes down for the first 4 minutes while the other keeps the ball; then swap roles.', '1-2 touch.', NULL, 'Vary tempo; hit wide areas and switch play.', '10v10', 20, 20, '50 x 50 yards', 45.7, 45.7, 8.0, false, false, false, NULL, 410),
  ('10v10 plus GKs attack the gate', 'small_sided_game', 'opposed', 'in_possession', 188, 188, 'AC Milan Session Example 1: Practice 4', 'Rene Meulensteen (Man Utd)', 'Attack through end gates and score, switching play.', 'Same 50 x 50 yard layout with end gates, now with goals and GKs.', 'Teams dribble through an end gate and then try to score past the GK.', NULL, NULL, 'Play at different tempos and hit wide areas to switch.', '10v10 + GKs', 22, 22, '50 x 50 yards', 45.7, 45.7, 12.0, true, true, true, NULL, 420),
  ('11v11 between the penalty areas', 'conditioned_game', 'opposed', NULL, 188, 188, 'AC Milan Session Example 1: Practice 5', 'Rene Meulensteen (Man Utd)', 'Opponent-specific game: press the key playmaker and switch play.', 'Pitch between the two penalty areas, 11v11.', 'Full game where one midfielder (Park Ji-sung) is told to mark and press the opposing deep playmaker (Scholes standing in for Pirlo).', NULL, NULL, 'Different tempos; hit wide areas to switch play.', '11v11', 22, 22, 'Between the penalty areas', NULL, NULL, 12.0, true, true, true, NULL, 430),
  ('11v11 in half a pitch', 'conditioned_game', 'opposed', NULL, 189, 189, 'AC Milan Session Example 2: Practice 4', 'Rene Meulensteen (Man Utd)', 'Tight-space 11v11 with a man-to-man press on the playmaker and switching play.', 'Half pitch, 11v11.', 'Same tactical instruction as session 1: one midfielder presses the deep playmaker; teams play at varying tempos and switch to wide areas.', NULL, 'Followed by 20 min extra finishing for forwards and wingers.', NULL, '11v11', 22, 22, 'Half pitch', NULL, NULL, 15.0, true, true, true, NULL, 440),
  ('8v2 one-touch rondo boxes', 'rondo', 'overload', 'in_possession', 194, 194, 'Session Example 1: Practice 2 (8v2 Boxes)', 'Rene Meulensteen (Man Utd)', 'Quick one-touch keep-ball with awareness and disguise.', 'Groups of 10 in 8 x 8 yard boxes; 8 players around the outside, 2 defenders inside.', 'Outside players keep the ball with one touch while the two inside work together to close angles and win it.', 'Aim for one touch; no return pass to the player who passed to you.', NULL, 'Know what is around you; quick feet; split the defenders or play around quickly; decide long or short; use disguise.', '8v2 per box', 10, NULL, '8 x 8 yards', 7.3, 7.3, 10.0, false, false, false, NULL, 450),
  ('Up-back-through activation passing routine', 'passing_unopposed', 'unopposed', 'in_possession', 195, 195, 'Session Example 1: Practice 3', 'Rene Meulensteen (Man Utd)', 'Get used to passing in different directions and distances with combinations and spin-off turns.', 'Central channel with players at A, B, C positions at both ends and D players wide by corner cones; blue cones act as defenders; two balls start at opposite ends.', 'A passes to B who lays off; A passes forward to C who spins off to receive; C lays back to B; B plays wide into D''s run; D dribbles to a corner cone, spins off it, dribbles the other way, spins again and passes back to the start; continuous rotation.', NULL, NULL, 'Quick interplay and carrying with spin-off turns; change the angle of attack; weight the pass in front of D so he need not slow.', 'Group, two balls at once', NULL, NULL, NULL, NULL, NULL, 10.0, false, false, false, NULL, 460),
  ('9v7 build-up, midfielder rotates out', 'phase_of_play', 'overload', 'in_possession', 196, 196, 'Session Example 1: Practice 4', 'Rene Meulensteen (Man Utd)', 'Build out from the GK against three forwards, with a central midfielder rotating out to the full-back area.', 'Reds 9 (GK, back four, midfielders) play a large goal; blues 7 with 3 forwards defend it; at the other end 2 wide pole gates and a central mini goal.', 'GK passes to a centre back, then to full back; the full back plays back or into the central midfielder; a midfielder rotates out between centre back and full back to receive and either carry forward or pass into space. Reds score by dribbling through a gate or into the mini goal.', 'If blues win it, restart.', NULL, 'Centre backs split wide when GK has it, full backs push high and wide; midfielders read when to rotate out; find space to play forward.', '9v7', 16, 16, 'About two thirds of a pitch', NULL, NULL, 10.0, true, true, true, NULL, 470),
  ('10v8 build-up, midfielder rotates in', 'phase_of_play', 'overload', 'in_possession', 197, 197, 'Session Example 1: Practice 5', 'Rene Meulensteen (Man Utd)', 'Create a back three against two forwards by dropping a midfielder between the centre backs.', 'Reds 10 v blues 8 with two forwards; three pole gates at the far end; GK and goal behind reds.', 'When the full back has the ball, a central midfielder drops between the centre backs (or a centre back moves central and a midfielder slides beside) to form a 3v2; a free centre back carries into midfield, full backs push high and wingers inside, then switch, dribble through a gate or pass in behind.', NULL, NULL, 'Know how to rotate in; move the ball quickly across the back three to drag the forwards; carry when there is time; cue for winger inside and full back on.', '10v8', 18, 18, 'About two thirds of a pitch', NULL, NULL, 10.0, true, true, true, NULL, 480),
  ('11v11 build-up rotations game', 'conditioned_game', 'opposed', 'in_possession', 198, 200, 'Session Example 1: Practice 6 (6a-6c)', 'Rene Meulensteen (Man Utd)', 'Apply the midfielder rotations in a full 11v11 build-up against 3 or 2 forwards.', 'Full pitch 11v11; reds build up from their GK in 4-3-3; blues defend first in a 4-3-3 (3 forwards), teams swap after 10 minutes.', 'Scenario 1: full backs high, a central midfielder rotates out to receive and the reds play forward via the centre back, a midfielder or between the lines. Teams swap roles after 10 minutes.', NULL, '6b: blues in 4-4-2 (2 forwards); a midfielder drops between the centre backs so a centre back carries forward, then diagonals between the lines or wide. 6c: GK kicks long; reds contest first and second ball and either attack at once (flick on in behind) or keep it and restart a ''second phase'' build-up with the same rotations, centre backs and full backs dropping to open out.', 'Open out quickly; know positions relative to GK, team-mates and opponents; recognise cue to rotate; vary GK kicks.', '11v11', 22, 22, 'Full pitch', NULL, NULL, 36.0, true, true, true, NULL, 490),
  ('4v4 plus 2 link players possession', 'possession', 'overload', 'in_possession', 202, 202, 'Session Example 2: Practice 3', 'Rene Meulensteen (Man Utd)', 'Keep possession with help from link players while defenders press as a unit.', '20 x 20 yard area; reds on the sides, blues inside; two yellow link players, one on a side and one inside.', 'Reds keep the ball with the two link players; blues press together to close angles and win it, and if they do the teams swap roles.', NULL, 'Add a second 20 x 20 box with one link player; complete a set number of passes then switch into the other box.', NULL, '4v4 (+2)', 10, 10, '20 x 20 yards', 18.3, 18.3, 8.0, false, false, false, NULL, 500),
  ('7v7 plus 2 possession with pole gates', 'positional_game', 'overload', 'in_possession', 203, 203, 'Session Example 2: Practice 4', 'Rene Meulensteen (Man Utd)', 'Know when to play around, away from or through the opposition with good possession and runs.', '38 x 48 yard area with 4 pole gates inside; 7v7 plus 2 link players.', 'Coach starts it; the team on the ball scores by receiving a pass through a gate or dribbling through one, using link players to create overloads and short interplay to make space.', '1 touch or 1-2 touches.', NULL, 'Look for spaces and switch; first touch into space after a pass through the poles; attack gates when on.', '7v7 (+2)', 16, 16, '38 x 48 yards', 43.9, 34.7, 10.0, false, false, true, NULL, 510),
  ('7v7 plus 3 GKs end zone possession', 'positional_game', 'overload', 'in_possession', 204, 204, 'Session Example 2: Practice 5', 'Rene Meulensteen (Man Utd)', 'Play out from the GK with width, depth and angles and move the ball end zone to end zone.', '30 x 35 yard area with an end zone at each end; GKs in the end zones (one at one end, two at the other), 7v7 in the middle.', 'Play starts from a GK; the team on the ball keeps it and moves it from one end zone GK to the other, choosing the moment to play through the lines. Defenders stay compact, press and after winning it keep it using the GKs.', '1-2 touch. Use 2, 3 or 4 GKs or replace with coach/defender.', 'Often preceded by 7v7 1-2 touch keep-ball in a 35 yard square (8 min).', 'Lose ball close the space, win ball make it big; defenders block lanes to GKs; attackers never stand where they block passing lanes.', '7v7 (+3 GKs)', 17, 17, '30 x 35 yards', 32.0, 27.4, 8.0, false, true, true, NULL, 520),
  ('Score then keep it conditioned game', 'conditioned_game', 'opposed', 'in_possession', 205, 205, 'Session Example 2: Practice 6', 'Rene Meulensteen (Man Utd)', 'Finish the session with a game focused on the topic: keeping possession once ahead.', 'Half a full pitch with two goals and GKs; 7v7 to 10v10 (diagram 8v8 + GKs); throw-ins but no offside or corners.', 'Both teams try to score first; the team that goes 1-0 up then just keeps the ball using both GKs while the other tries to win it and equalise, after which both try to score again.', 'Conditions change with the topic or opponent, e.g. cut-back goals, shots from outside the box or crosses count double.', NULL, NULL, '7v7, 8v8, 9v9 or 10v10 + GKs', 16, 22, 'Half pitch', NULL, NULL, 14.0, true, true, true, NULL, 530),
  ('Switching play four-corner warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 207, 210, 'Session Example 3: Practice 3 (3a-3d)', 'Rene Meulensteen (Man Utd)', 'Switch the ball from side to side in four progressive variations.', 'Area marked across the centre circle; 12-16 players in lines at the four corners plus players at middle positions on each side; four balls start at once from the corners.', '3a: corner players pass to a middle player who switches the ball across to the opposite corner; reds start with a short pass and finish long, blues the reverse; everyone follows their pass.', NULL, '3b: corner player dribbles towards halfway before passing; receiver also dribbles before the final switch pass. 3c: add a 1-2 and a pass into the team-mate''s run, who dribbles over halfway and switches. 3d: corner player does an up-and-down move (e.g. Cruyff turn) then passes; receiver does a spin-off turn before the switch.', 'Drive through the ball, open up, keep it low; keep the ball close when dribbling; cushion the pass to dribble on; weight short passes for first-time play; do moves in small spaces; be brave to switch in matches.', '12-16', 12, 16, 'Around the centre circle', NULL, NULL, 28.0, false, false, false, NULL, 540),
  ('Switching play warm-up: interplay and turns', 'passing_unopposed', 'unopposed', 'in_possession', 209, 210, 'Session 3: Practice 3c / 3d', 'Meulensteen (Man Utd)', 'Switching the ball from one flank to the other with a short combination or a skill move first.', 'Same four-corner set-up as warm-up 3a/3b around the centre circle: groups at each corner, mannequins in the middle, 4 balls starting from all corners at once.', '3c: the corner player dribbles toward halfway, plays a one-two and a pass into a team-mate''s run; that player dribbles over halfway and plays the long switch. 3d: the corner player does an up-and-down move (e.g. Cruyff turn), passes to the nearest team-mate, who receives with a spin-off turn and then plays the switch. Everyone follows their pass.', 'Players follow their pass; all four corners start together.', '3c (short interplay) then 3d (individual moves and turns) are successive variations of the same routine.', 'Short passes weighted so the next pass can be first time; accurate to the correct foot; moves done tight with the ball close; be brave and play the switch often.', NULL, NULL, NULL, 'Centre of the pitch around the centre circle', NULL, NULL, 14.0, false, false, true, NULL, 550),
  ('8v8+4 switching game, limited touches', 'positional_game', 'overload', 'in_possession', 211, 211, 'Session 3: Practice 4a', 'Meulensteen (Man Utd)', 'Switching play fully and diagonally from one side of the pitch to the other.', 'Middle area split into four zones A-D with an 8v8; four yellow neutrals each in an outside wide zone 1-4; coach on the side with balls.', 'Coach plays in; the team in possession works the ball to switch diagonally (A to 4, B to 2, C to 3, D to 1). A switch received by the neutral in his zone scores a point and the coach plays a new ball to a defender of the same team; on a failed switch the coach gives a ball to the other team.', '1 touch inside the centre circle and around halfway, 1-2 touches elsewhere; switch must be diagonal; successful switch = 1 point.', NULL, 'Pick the right moment to switch; diagonal passes; good technique on the switch; wide players read the cue, create width and get ready to receive.', '8v8+4', 20, 20, NULL, NULL, NULL, 10.0, false, false, true, NULL, 560),
  ('9v9+2 switching game, wider zones', 'positional_game', 'overload', 'in_possession', 212, 212, 'Session 3: Practice 4b', 'Meulensteen (Man Utd)', 'Diagonal switches of play with wide players timing their movement.', '9v9 with only 2 yellow neutrals, who move up and down the now double-width outside zones; four inner zones A-D as before.', 'Teams try to switch diagonally (A to 4, B to 2, C to 3, D to 1); successful switch = point and a fresh ball to the same team from the coach. Neutrals can now join the build-up as well as receive the switch.', '1 touch in centre circle and around halfway, 1-2 touches elsewhere; switches must be diagonal.', NULL, 'The wide player (winger or full back) must judge when to push higher and time the run for the switch.', '9v9+2', 20, 20, NULL, NULL, NULL, 10.0, false, false, true, NULL, 570),
  ('9v9+2 switching game with crossing to goals', 'conditioned_game', 'overload', 'in_possession', 213, 213, 'Session 3: Practice 5', 'Meulensteen (Man Utd)', 'Switching play and then attacking the box from the wide area to finish.', 'Same zoned 9v9+2 area as 4b with a full-size goal and GK added at each end.', 'After a switch is received in a wide zone (e.g. C to 3), the yellow neutral carries the ball down the line and crosses; a set number of the team in possession (3) attack the box to score.', '1 touch in centre circle and around halfway, 1-2 elsewhere.', NULL, 'Right moment to switch; pace and accuracy on the switch; wide player carries the ball forward with first touch; quality final ball; forwards time coordinated box runs and finish clinically.', '9v9+2 +2 GKs', 22, 22, NULL, NULL, NULL, 10.0, true, true, true, NULL, 580),
  ('Switching play 9v9+2 link players game', 'conditioned_game', 'overload', 'in_possession', 214, 214, 'Session 3: Practice 6', 'Meulensteen (Man Utd)', 'Using switches of play in a match situation, finishing with crosses and timed runs.', 'Box-to-box 9v9 with 2 neutral link players in midfield and GKs in full-size goals.', 'Normal game focused on the session''s theme: switch play, cross, time runs and finish.', 'Goal after a successful switch counts double; goal after combining across to one side and then switching back counts triple.', NULL, 'Create width and depth; think forward, look forward, play forward; use the link players to switch; make a full switch; dribble to the by-line and cross.', '9v9+2 +GKs', 22, 22, 'Box to box', NULL, NULL, 10.0, true, true, true, NULL, 590),
  ('Breaking the lines passing warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 216, 218, 'Session 4: Practice 3a / 3b / 3c', 'Meulensteen (Man Utd)', 'Passing forward through lines with players coming off mannequins, building rhythm and accuracy.', 'Two identical stations side by side, each with positions A-G around mannequins in a half-pitch shape; two balls running at once.', 'A passes to B who comes off a mannequin; B lays into A''s run; A passes to C who checks off a mannequin; C lays into B''s run; B plays the fifth pass on to continue; players rotate A-B-C-D-E-F-G. Variation 1 clockwise, Variation 2 anticlockwise.', '2 balls at once; everyone moves on to the next position.', '3b: the third pass becomes a diagonal ball to the opposite side, with crossing runs. 3c: one ball only and free decisions - players pick any available option, skip a line, drive forward, and fill whichever position is free.', 'Short passes done well in tight space; come off the mannequin at an angle, sideways-on; strong through pass; watch the traffic in the middle; when the gap is there, play it; keep the 4 middle positions filled.', NULL, NULL, NULL, NULL, NULL, NULL, 12.0, false, false, true, NULL, 600),
  ('3-zone 8v4 playing through midfield line', 'positional_game', 'overload', 'in_possession', 219, 219, 'Session 4: Practice 4', 'Meulensteen (Man Utd)', 'Recognising the moment to pass forward through a midfield line.', 'Area split into three equal zones; 4 reds in one end zone, 4 blue defenders in the middle zone, 4 yellows in the far zone; players stay in their zones.', 'Coach plays to the reds, who move the ball quickly to find the moment to pass through the 4 blues to the yellows; the yellows move to receive in gaps and play back the other way.', 'Players stay in their zones; swap the middle group after 4 interceptions or a set time.', NULL, 'Know when to delay or speed up (rhythm); firm passes through gaps; receivers keep moving into gaps; defending four work together and leave no gaps.', '4v4v4 (8v4)', 12, 12, NULL, NULL, NULL, 12.0, false, false, true, NULL, 610),
  ('9v9 zonal game, passing to forwards between lines', 'conditioned_game', 'overload', 'in_possession', 220, 220, 'Session 4: Practice 5', 'Meulensteen (Man Utd)', 'Breaking through the midfield line to forwards and going to goal.', '9v9 plus GKs; two banks of 4 midfielders (red zone and blue zone) in the middle who must stay in their zones; 3 forwards each side behind the opposing midfield.', 'Coach starts with a pass to a midfielder; the team must break through the opposing midfield line into their forwards and exploit a 3v2 to score. If the defending midfielders intercept they try to hit their own forwards straight away or keep the ball.', 'Midfield fours stay in their zone; always restart from the coach.', 'Start from the GK: centre backs open out and try to play through the opposing forwards into a midfielder.', 'Rhythm (delay or speed up); firm passes through gaps; quick clinical finishing; forwards keep moving to find gaps; defending team stays compact.', '9v9 +GKs', 20, 20, NULL, NULL, NULL, 8.0, true, true, true, NULL, 620),
  ('11v11 between the lines with advanced full backs', 'conditioned_game', 'opposed', 'in_possession', 221, 221, 'Session 4: Practice 6', 'Meulensteen (Man Utd)', 'Midfield releasing full backs on forward runs after playing into forwards between the lines.', '11v11 (reds 4-4-3 vs blues 4-4-2) with two marked middle zones for the midfield units.', 'Coach passes to a midfielder; reds play through the blue midfield line to a forward, then use overlapping full back runs for a 5v2 to score. Blues who intercept break quickly to their forwards or advanced full backs.', NULL, 'Start from the GK: centre backs split, play into midfield; midfielders encouraged to drop or rotate out to support the build-up.', 'Full backs hold and time the forward run and deliver a quality ball; forwards make coordinated near/middle/far post runs; crisp passing and clinical finishing.', '11v11', 22, 22, NULL, NULL, NULL, 10.0, true, true, true, NULL, 630),
  ('End to end 4v4+3 three-zone possession', 'positional_game', 'overload', 'in_possession', 224, 224, 'Session 5: Practice 3', 'Meulensteen (Man Utd)', 'Keeping possession with the spare man and transferring the ball through the middle to the far end.', 'Two 20x15 yard end zones and a 20x10 middle zone (20x50 total); 4 mannequins in the middle; a yellow link player in each zone.', 'Coach plays in; the reds keep the ball 5v4 in one end and pass into the middle link player avoiding the mannequins, who plays to the link player at the far end; all players then move across and the reds try to bring it back. Blues who win it swap roles with the reds.', 'After a successful transfer the end and middle link players swap positions.', NULL, 'Find the spare man and pick the moment to go forward into the middle; quick transfer to the other end; one and two touch rhythm in tight space.', '4v4+3', 11, 11, '20 x 50 yards', 45.7, 18.3, 12.0, false, false, true, NULL, 640),
  ('Three-zone 7v7+1 attacking overloads', 'small_sided_game', 'overload', 'in_possession', 225, 225, 'Session 5: Practice 4', 'Meulensteen (Man Utd)', 'Building through zones to create numerical overloads, then reacting to second and third balls.', 'Three zones on part of the pitch: 50x18 yd low zone (2v1), 50x24 yd middle (4v3 with a link player), 50x18 yd end zone (3v2 once attackers join); goals with GKs.', 'Ball 1: coach to GK, reds build out 2v1 and into the middle 4v3, then 2 players join the end zone for a 3v2 to score. Ball 2: coach gives the reds a new ball in midfield to attack again. Ball 3: coach gives the blues a ball to counter. Blues who win the ball during balls 1-2 counter straight away.', NULL, NULL, 'Open the pitch big in the low zone; create angles and dribble forward for 4v3/5v3; drag players to make overloads; choose the side to attack; make 3v2 or 4v2 in the end zone; keep momentum on the second ball.', '7v7+1 +GKs', 17, 17, 'Zones 50x18, 50x24, 50x18 yards', NULL, 45.7, 10.0, true, true, true, NULL, 650),
  ('Three-zone 9v9 attacking overloads game', 'conditioned_game', 'overload', 'in_possession', 226, 226, 'Session 5: Practice 5', 'Meulensteen (Man Utd)', 'Build-up through zones creating 3v2, 4v3 and 1v1 situations.', 'Bigger version of the previous practice: zones about 60x18, 60x28 and 60x18 yards, link player removed, 9v9 with GKs.', 'Ball 1: coach to GK and reds build through the zones to score. Ball 2: second ball to the reds to attack again. Ball 3: ball to the blues for a quick counter.', NULL, NULL, 'Rotations - defensive midfielder drops in to help the build-up; dribble forward when possible; read opponents'' positions; use the 3v2 in the low zone.', '9v9 +GKs', 20, 20, 'Zones 60x18, 60x28, 60x18 yards', NULL, 54.9, 10.0, true, true, true, NULL, 660),
  ('11v11 three-zone attacking overloads, multiple phases', 'conditioned_game', 'overload', 'in_possession', 227, 227, 'Session 5: Practice 6', 'Meulensteen (Man Utd)', 'Midfield rotations and advanced full backs creating overloads in attack.', 'Full pitch in three zones, 11v11 with GKs.', 'Ball 1: coach to GK, reds build through the zones to score; ball 2: new ball to reds to attack again; ball 3: ball to blues to counter. Reds aim for a 5v4 in the end zone with the full back crossing.', NULL, NULL, 'Midfielders find space and decide to drop or move wide; CMs rotate out when the ball goes back; full backs push high and wingers come inside as a front three.', '11v11', 22, 22, 'Full pitch', NULL, NULL, 10.0, true, true, true, NULL, 670),
  ('Crosses and box runs warm-up drill', 'finishing', 'unopposed', 'in_possession', 229, 229, 'Session 6: Practice 3', 'Meulensteen (Man Utd)', 'Delivering crosses and timing box runs to finish.', '12 players; on each wing 2 feeders, crossers outside the box at different spots, GK in goal, mannequins in the box.', 'Players cross from varied positions outside the box into different areas in front of goal, alternating left and right; a pair attacks every cross with runs to different areas.', 'Alternate sides.', NULL, 'Pinpoint crosses and know which type to deliver; correct technique; arrive late and fast; accurate finishing with head and feet; jump, arch and hang to head.', '12 players + GK', 13, 13, NULL, NULL, NULL, 11.0, true, true, true, NULL, 680),
  ('Early back post crosses v 2 defenders', 'finishing', 'opposed', 'in_possession', 230, 230, 'Session 6: Practice 4', 'Meulensteen (Man Utd)', 'Finishing early crosses into the space behind the centre backs.', 'Attacking half with 2 blue centre backs and a GK; midfielders around the centre circle with balls; wide players on both flanks; forwards on the edge of the box.', 'Midfielders combine and switch the ball out to a winger or full back, who crosses low and hard first time or after a touch into the space between GK and defenders; forwards burst past the centre backs to score.', NULL, NULL, 'Quality pass wide; wide player decides between one-touch cross and controlling first; bend the ball behind the centre backs; timed runs; react to rebounds.', 'Attackers v 2 defenders + GK', NULL, NULL, 'Attacking half', NULL, NULL, 9.0, true, true, true, NULL, 690),
  ('Back post chips or cut backs v 4 defenders', 'finishing', 'opposed', 'in_possession', 231, 231, 'Session 6: Practice 5', 'Meulensteen (Man Utd)', 'Combination play leading to wide service, chipped to the back post or cut back.', 'Half pitch: red centre backs and midfielders in build-up positions, wingers/full backs wide, blue back four and GK, a spare GK feeding from the end line.', 'Spare GK distributes to a red centre back; reds rotate through midfield to get the ball wide toward the by-line; the wide player chips over GK and defenders to the back post or cuts back to the edge of the box; red attackers burst in to score.', NULL, NULL, 'CBs control efficiently; wide players show to receive; rehearsed quick midfield interplay; under/overlaps to get wide; be composed approaching a cut back and choose shot, cross or clever pass.', NULL, NULL, NULL, 'Half pitch', NULL, NULL, 9.0, true, true, true, NULL, 700),
  ('Crosses and box runs dynamic zonal 9v9', 'conditioned_game', 'opposed', 'in_possession', 232, 232, 'Session 6: Practice 6', 'Meulensteen (Man Utd)', 'Crossing and box runs inside a game with keep-ball build-up.', 'Half pitch split into 9 zones; 4v4 in the middle, 2 wingers each in the wide zones, 2 defenders in each penalty area, GKs.', 'GK throws to a winger who crosses for 4 runners (3 forwards plus a midfielder for second balls); after a goal the play restarts from either GK. An overhit cross is recycled by the far winger. If no cross is on, reds drop into the middle and build with keep-ball and 1-2s to find the winger again; blues who win it feed their own wingers.', NULL, NULL, 'Composed quality crosses; timed and connected box runs; be brave; defenders read flight and head clear; use centre backs and wingers to exploit the overload.', '9v9 +GKs', 20, 20, 'Half pitch', NULL, NULL, 9.0, true, true, true, NULL, 710),
  ('Passing, showing to receive, turn and finish', 'combination', 'unopposed', 'in_possession', 235, 235, 'Session 7: Practice 3', 'Meulensteen (Man Utd)', 'Passing, receiving, turning away from a defender and finishing.', 'Two groups of 8, one on each side of the attacking half, positions A-G set around mannequins, GK in goal.', 'A to B in front of a mannequin, B lays inside for A, A to C, C inside to D, D to E, E lays back to F, F forward to G in front of a mannequin; G turns away and shoots. Players rotate A to G after each pass.', NULL, NULL, NULL, '16 players in two groups of 8 + GK', 17, 17, 'Attacking half', NULL, NULL, 12.0, true, true, true, NULL, 720),
  ('Takeover combination with dribble, disguise and finish', 'combination', 'unopposed', 'in_possession', 236, 236, 'Session 7: Practice 4', 'Meulensteen (Man Utd)', 'Taking the ball over from a dribbling team-mate to switch the direction of attack and shoot.', 'Two groups, one on each side of the attacking half; players at A (feeding near the goal line), B (central midfield), C and D (winger), GK.', 'A plays long to B, who drives forward at an angle and backheels with disguise for C to take over; C dribbles the other way and backheels for D''s inside run; D dribbles at goal and shoots.', NULL, NULL, 'Drive with the ball and backheel with disguise at the right moment; finish with power from outside the box or curl around the GK.', NULL, NULL, NULL, 'Attacking half', NULL, NULL, 9.0, true, true, true, NULL, 730),
  ('Functional 3-ball attacking routine', 'combination', 'unopposed', 'in_possession', 237, 239, 'Session 7: Practice 5', 'Meulensteen (Man Utd)', 'Penetrating passes, interplay, crossing, timed runs and finishing in a rehearsed team pattern.', 'Attacking half with mannequins as a back four and poles; a midfield and attack line-up (e.g. full back, CMs, wide players, striker) and a GK.', 'Ball 1: square pass, then a low hard pass between mannequins for the overlapping right back to cut back for timed near-post and back-post runs. Ball 2: a midfielder carries forward, plays to a team-mate dropping back, who lays off for a forward run and shot from the edge of the box. Ball 3: diagonal pass for a midfielder running round the pole, who slips a pass behind the mannequins for a timed run, then a cross-box pass for a back-post finish.', 'Everyone returns to start positions between balls.', NULL, 'Pass weight and timing of the runs are key so crosses can be hit first time; go late and arrive fast; drop quickly to give an option; shoot with laces/instep into the corners.', NULL, NULL, NULL, 'Attacking half', NULL, NULL, 15.0, true, true, true, NULL, 740),
  ('6v5 attack v defence in half a pitch', 'phase_of_play', 'overload', 'in_possession', 240, 240, 'Session 7: Practice 6', 'Meulensteen (Man Utd)', 'Applying the session''s attacking combinations in a game-like attack against a back line.', 'Half pitch; reds: 2 central midfielders, 4 wingers (2 rest each phase), 2 forwards; blues: back four plus a defensive midfielder and GK; target area at halfway.', 'GK throws out and the reds attack 6v5, getting around or through the defensive line with quick movement and runs behind. If blues win it they push up together and pass to the GK in the blue area.', NULL, NULL, 'Use the session''s combinations: one-touch play, dribble and leave the ball, pass-move-cross-finish.', '6v5 + GK', 12, 14, 'Half pitch', NULL, NULL, 25.0, true, true, true, NULL, 750),
  ('Speed, agility and finishing circuit', 'finishing', 'unopposed', NULL, 243, 243, 'Session 8: Practice 3', 'Meulensteen (Man Utd)', 'Speed and agility work ending in different types of finish.', 'Three stations across the edge of the area facing three goals: A with poles to run round, B a pole slalom to a yellow pole gate, C a pole slalom.', 'A runs round poles, sprints at goal and finishes a coach''s ground or air ball (shot or header). B slaloms through poles and the gate and volleys a coach''s throw. C slaloms and finishes a coach''s ground or air ball. After 4 reps move on A-B-C.', '4 repetitions per station then rotate.', NULL, 'Good first touch then finish; body balance and arm movement; strike through the middle of the ball; accuracy before power; attack headers and time the jump.', NULL, NULL, NULL, NULL, NULL, NULL, 18.0, true, true, true, NULL, 760),
  ('4v4+1 speed finishing and blocking game', 'small_sided_game', 'overload', 'in_possession', 244, 244, 'Session 8: Practice 4', 'Meulensteen (Man Utd)', 'Moving the ball quickly with clever runs and shooting fast; defending by blocking shots.', 'Two games side by side; attacking team of a midfielder, 2 wingers, a forward plus a yellow link player vs a back four and GK; shooting zones marked.', 'Attackers play at high intensity, keep the ball moving, make runs and combinations and shoot whenever possible using the 5v4. Defenders work together to get out and block shots.', 'Attackers score with goals, defenders score by blocking shots; 4 x 2 min games, teams rotate so all play each other.', NULL, 'Use disguise (feint to shoot) and skills to set up the shot.', '4v4+1 + GK', 10, 20, NULL, NULL, NULL, 8.0, true, true, true, NULL, 770),
  ('8v8+2 speed finishing and blocking game', 'conditioned_game', 'overload', 'in_possession', 245, 245, 'Session 8: Practice 5', 'Meulensteen (Man Utd)', 'Quick attacks with an extra man and shot-blocking defending in a bigger game.', '20 players including GKs over the whole area with shooting zones; 2 link players.', 'Game starts from a GK; attackers play fast with 10v8 using the link players and shoot when possible; defenders block shots and counter fast when they win it.', NULL, NULL, 'Use extra players to attack quickly; shoot with disguise; follow up shots for rebounds; clever runs off the back four; stay compact, press the ball with cover, be brave when blocking.', '8v8+2 +GKs', 20, 20, NULL, NULL, NULL, 12.0, true, true, true, NULL, 780),
  ('Varied attacks and finishing large sided game', 'conditioned_game', 'overload', 'in_possession', 246, 246, 'Session 8: Practice 6', 'Meulensteen (Man Utd)', 'Varying attacks through the centre and out wide, finishing crosses and central chances.', 'Three middle zones and two wide zones, shooting zones; 6v4 centrally, 2v1 out wide with resting full backs/wingers alternating.', 'GK kicks or throws to a winger or central midfielder, alternating between central attacks (exploit the 6v4) and wide attacks (2v1 overlap then cross). Next time out wide one winger joins and a wide player supports behind for a deep cross. Blues defend central attacks and crosses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30.0, true, true, true, NULL, 790),
  ('11v11 defensive shape and movements warm-up', 'defending', 'passive', 'out_of_possession', 248, 248, 'Session 9: Practice 3', 'Meulensteen (Man Utd)', 'Team shape and coordinated defensive movements in response to the ball.', 'Pitch marked into 12 areas; blues pass the ball around, reds hold a team shape.', 'Blues circulate the ball; reds move as a unit: step up when ball goes back, shift across when it goes sideways, hold when in shape, drop when the opponent has time to pass forward. Swap after 8 minutes.', 'Swap roles after 8 minutes.', '11v11 game with lots of coaching.', 'Move up, shift, hold, drop.', '11v11', 22, 22, NULL, NULL, NULL, 16.0, false, true, false, NULL, 800),
  ('Pressing high in a tactical 10v11', 'defending', 'opposed', 'out_of_possession', 249, 249, 'Session 9: Practice 4', 'Meulensteen (Man Utd)', 'Collective high pressing from the GK''s pass to stop the opposition building up.', 'Blues with a GK build from their own half; reds press; a dashed line beyond the blue half.', 'Blue GK plays to a centre back; blues try to play or dribble past the dashed line; reds press high to win it quickly.', 'If reds win it high they must score within 20 seconds; won in midfield they can attack or keep it.', 'Full pitch 11v11 game.', 'Good starting positions; front three in half positions covering two players; recognise the trigger; force play wide; hunt any player facing his own goal or head down.', '10v11', 21, 22, NULL, NULL, NULL, 9.0, true, true, true, NULL, 810),
  ('Defensive shape and recovery 10v10 transition game', 'transition', 'opposed', 'to_defend', 250, 250, 'Session 9: Practice 5', 'Meulensteen (Man Utd)', 'Defensive organisation and recovery runs to stop counter-attacks.', 'Reds attack 3 mini goals; blues defend a central zone with side zones either side and counter to a big goal with GK.', 'Coach passes to a red defender; reds build and try to score in any mini goal. Blues stay compact centrally and force play wide. When blues win it they counter fast at the GK goal and red defenders sprint back.', NULL, NULL, 'React fast on turnover; nearest player presses and delays; press when opponent faces own goal; drop off when he has time; anticipate forward passes and intercept.', '10v10 + GK', 21, 21, NULL, NULL, NULL, 9.0, true, true, true, NULL, 820),
  ('11v11 transition game with scoring variations', 'transition', 'opposed', 'to_defend', 251, 251, 'Session 9: Practice 6', 'Meulensteen (Man Utd)', 'Rest defence and quick recovery after attacks, against counters.', 'Full pitch 11v11; blue scoring targets in four stages: dashed line, pole gates, 4 mini goals, big goal with GK.', 'Ball 1: coach to a red centre back, reds build and score. Ball 2: second ball to reds to attack again. Ball 3: ball to blues to counter while reds sprint back.', 'Blues score by: 1st 6 min dribbling over the line, 2nd through pole gates, 3rd in mini goals, 4th in the big goal past a GK.', 'Four 6-minute phases with the blue target changing.', 'Centre backs provide rest defence behind the ball, delay and force to one side; full backs and midfielders recover as fast as possible.', '11v11', 22, 22, 'Full pitch', NULL, NULL, 24.0, true, true, true, NULL, 830),
  ('7v7+7 possession game warm-up', 'possession', 'overload', 'in_possession', 253, 253, 'Session 10: Practice 3', 'Meulensteen (Man Utd)', 'Possession with link players and one-touch play under pressure.', 'Area around the centre circle; 7v7 plus 7 yellow link players.', 'Teams keep the ball using the link players. First 6 min: link players placed as shown; second 6 min: 2 link players at each end only; third 6 min: one in the centre circle, 2 at each end, 1 on each side.', 'Winning team keeps the ball; 1 touch in centre circle for all; link players 1-2 touches; change link players often.', 'Link player positions change each 6 minutes.', NULL, '7v7+7', 21, 21, NULL, NULL, NULL, 18.0, false, false, false, NULL, 840),
  ('7v7+7 outside link players transition game', 'small_sided_game', 'overload', 'to_attack', 254, 254, 'Session 10: Practice 4', 'Meulensteen (Man Utd)', 'Using link players for width and depth to break, plus supporting runs to finish.', 'Width of the box by half a pitch; 7v7 with 7 outside link players and goals with GKs.', 'Coach passes to a team, which builds up and tries to score; the other team wins it and counters. Restarts from the coach after each phase.', 'Can only score after using an outside link player; link players 1 touch; change link players each 4 minute rep.', NULL, 'Know where link players are; use them to move the ball quickly; recognise when to break forward; supporting runs.', '7v7+7 +GKs', 23, 23, 'Box width x half a pitch', NULL, 40.2, 16.0, true, true, true, NULL, 850),
  ('7v7+1 wave transition game with GKs', 'transition', 'overload', 'to_attack', 255, 255, 'Session 10: Practice 5', 'Meulensteen (Man Utd)', 'Changing mindset immediately on winning or losing the ball.', 'Three zones and a halfway line; 7 per team plus a link player and 2 GKs; a third team (whites) waits off the pitch.', 'Ball 1: coach to GK, reds build with the link player and attack; blues counter if they win it. Ball 2: second ball to the red GK, reds go again. Ball 3: ball to blues for a counter. Then whites replace reds, reds rest, blues become attackers and whites defend.', 'Waves of 3 balls then teams rotate.', NULL, 'Quick 1-2 touch interplay; forward runs; quality final balls and cut backs; win it - sprint forward, lose it - sprint back.', '7v7+1 +GKs (+7 waiting)', 17, 24, NULL, NULL, NULL, 16.0, true, true, true, NULL, 860),
  ('11v11 possession v defend plus counter', 'transition', 'opposed', 'to_attack', 256, 256, 'Session 10: Practice 6', 'Meulensteen (Man Utd)', 'Winning the ball by interception and playing forward fast behind the defensive line.', 'Area between one by-line and the opposite penalty box, with 2 end zones; goal with GK.', 'Coach passes to a defender on either team; blues build and try to score; reds win it and counter fast, aiming for a final ball into the end zone to score. Blue defenders recover.', 'Ball must stay on the ground.', 'Finish the session with a normal 11v11 in the same area focused on possession v defence and counter.', 'Read and intercept passes; defend side-on to step in front; play forward early on regaining; see the space and forward runs.', '11v11', 22, 22, NULL, NULL, NULL, 9.0, true, true, true, NULL, 870)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'ren-meulensteen-man-utd-methods-of-success-2007-2013-ren-s-coaching-philosophy-a') b;
INSERT INTO schema_migrations (filename) VALUES ('2906-exercises-book-ren-meulensteen-man-utd-methods-of-success-2007-2013-ren-s-c.sql') ON CONFLICT DO NOTHING;
COMMIT;
